import { test, expect } from '@playwright/test';

test.describe('HTTP Status Codes Verification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
  });

  test('should navigate to 200 status code page and verify response text', async ({ page }) => {
    // Click the link with text '200'
    const link200 = page.getByRole('link', { name: '200' });
    await link200.click();

    // Verify URL contains '/status_codes/200'
    await expect(page).toHaveURL(/\/status_codes\/200/);

    // Verify page body contains the expected text
    const bodyText = page.locator('body');
    await expect(bodyText).toContainText('This page returned a 200 status code');
  });

  test('should navigate to 404 status code page and verify response text', async ({ page }) => {
    // Click the link with text '404'
    const link404 = page.getByRole('link', { name: '404' });
    await link404.click();

    // Verify URL contains '/status_codes/404'
    await expect(page).toHaveURL(/\/status_codes\/404/);

    // Verify page body contains the expected text
    const bodyText = page.locator('body');
    await expect(bodyText).toContainText('This page returned a 404 status code');
  });

  test('should return to status codes page and verify navigation flow', async ({ page }) => {
    // Click the link with text '200'
    const link200 = page.getByRole('link', { name: '200' });
    await link200.click();

    // Verify we're on the 200 page
    await expect(page).toHaveURL(/\/status_codes\/200/);

    // Navigate back to status codes page
    await page.goBack();

    // Verify we're back on the main status codes page
    await expect(page).toHaveURL(/\/status_codes$/);

    // Click the link with text '404'
    const link404 = page.getByRole('link', { name: '404' });
    await link404.click();

    // Verify we're on the 404 page
    await expect(page).toHaveURL(/\/status_codes\/404/);
    const bodyText = page.locator('body');
    await expect(bodyText).toContainText('This page returned a 404 status code');
  });
});
